// Update text nodes in place: never replace forms, buttons or GTM target elements.
(() => {
  const messages = window.DataPulseMessages;
  const supported = ['pt-BR', 'en', 'es'];
  const KEY = 'datapulse.language';
  let language = 'pt-BR';
  try {
    const saved = localStorage.getItem(KEY);
    if (supported.includes(saved)) language = saved;
  } catch { /* Language selection still works without persistent storage. */ }
  const originals = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement.closest('script, style, #site-language')) continue;
    if (messages[node.textContent.trim()]) originals.push({node, source:node.textContent});
  }
  const attributes = [];
  document.querySelectorAll('[aria-label], [placeholder], meta[name="description"]').forEach(element => {
    for (const name of ['aria-label', 'placeholder', 'content']) {
      const source = element.getAttribute(name);
      if (source && messages[source]) attributes.push({element,name,source});
    }
  });
  const title = document.title;
  const selector = document.querySelector('#site-language');
  const translate = source => messages[source]?.[language] || source;
  window.DataPulseI18n = {t:translate, get language() { return language; }};
  const errors = {
    'pt-BR': {required:'Preencha este campo.', email:'Informe um endereço de e-mail válido.', select:'Selecione uma opção.'},
    en: {required:'Please fill out this field.', email:'Please enter a valid email address.', select:'Please select an option.'},
    es: {required:'Completa este campo.', email:'Introduce una dirección de correo electrónico válida.', select:'Selecciona una opción.'}
  };
  function validate(field) {
    field.setCustomValidity('');
    if (field.validity.valueMissing) field.setCustomValidity(errors[language][field.tagName === 'SELECT' ? 'select' : 'required']);
    else if (field.validity.typeMismatch) field.setCustomValidity(errors[language].email);
  }
  document.querySelectorAll('#lead-form input, #lead-form select').forEach(field => {
    field.addEventListener('invalid', () => validate(field));
    field.addEventListener('input', () => field.setCustomValidity(''));
    field.addEventListener('change', () => field.setCustomValidity(''));
  });
  function apply(next) {
    if (!supported.includes(next)) return;
    language = next;
    document.documentElement.lang = language;
    selector.value = language;
    originals.forEach(({node,source}) => {
      node.textContent = source.replace(source.trim(), translate(source.trim()));
    });
    attributes.forEach(({element,name,source}) => element.setAttribute(name,translate(source)));
    document.title = translate(title);
    const menu = document.querySelector('.menu-toggle');
    menu.setAttribute('aria-label', translate(menu.getAttribute('aria-expanded') === 'true' ? 'Fechar menu' : 'Abrir menu'));
    document.querySelectorAll('#lead-form input, #lead-form select').forEach(field => {
      if (field.validity.customError) validate(field);
    });
  }
  selector.addEventListener('change', () => {
    apply(selector.value);
    try { localStorage.setItem(KEY, language); } catch { /* In-memory fallback. */ }
  });
  apply(language);
})();

